/**
 * Execute expertise sync to `teacher_expert` database table
 */
async function syncExpertiseToDatabase() {
  console.log(`[Antigravity AI] Applying ${EVALUATION_RECORDS.length} teacher-subject expertise evaluations...`);
  
  let inserted = 0;
  let updated = 0;

  for (const item of EVALUATION_RECORDS) {
    const existing = await db('teacher_expert')
      .where({ teacher_id: item.teacher_id, subject_id: item.subject_id })
      .first();

    if (existing) {
      await db('teacher_expert')
        .where({ id: existing.id })
        .update({ score: item.score });
      updated++;
    } else {
      await db('teacher_expert').insert({
        teacher_id: item.teacher_id,
        subject_id: item.subject_id,
        score: item.score
      });
      inserted++;
    }
  }

  console.log(`[Antigravity AI] Complete: ${inserted} inserted, ${updated} updated.`);
  return { total: EVALUATION_RECORDS.length, inserted, updated };
}

module.exports = {
  EVALUATION_RECORDS,
  syncExpertiseToDatabase
};

if (require.main === module) {
  syncExpertiseToDatabase()
    .then(res => {
      console.log('Result:', res);
      process.exit(0);
    })
    .catch(err => {
      console.error('Error:', err);
      process.exit(1);
    });
}

